# enumerate all monochrome rectangles >= 3x3 (all rows same run overlap)
R,C=len(grid),len(grid[0]); rects=[]
for r1 in range(R):
 for c1 in range(C):
  color=grid[r1][c1]
  for r2 in range(r1+2,R):
   if any(grid[r2][c]!=color for c in range(c1,C)): break
   # cumulative common horizontal until mismatch each row
   maxc=C
   for rr in range(r1,r2+1):
    cc=c1
    while cc<maxc and grid[rr][cc]==color: cc+=1
    maxc=cc
   if maxc-c1>=3: rects.append((r2-r1+1,maxc-c1,r1+1,c1+1,r2+1,maxc,color))
sorted(rects,reverse=True)[:30]

