# full monochrome regions, connected 4-neighbor components, grouped size
from collections import deque
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if (r,c) in seen: continue
  col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   x,y=q.pop(); comp.append((x,y))
   for z in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
    a,b=z
    if 0<=a<R and 0<=b<C and z not in seen and grid[a][b]==col:
     seen.add(z);q.append(z)
  if len(comp)>=6: comps.append((len(comp),col,min(x for x,y in comp)+1,max(x for x,y in comp)+1,min(y for x,y in comp)+1,max(y for x,y in comp)+1))
sorted(comps,reverse=True)[:30]

