   for c2 in range(c1+2,C):
    if all(grid[r][c]==col for r in range(r1,r2+1) for c in range(c1,c2+1)):
     canup=r1>0 and all(grid[r1-1][c]==col for c in range(c1,c2+1))
     candown=r2+1<R and all(grid[r2+1][c]==col for c in range(c1,c2+1))
     canleft=c1>0 and all(grid[r][c1-1]==col for r in range(r1,r2+1))
     canright=c2+1<C and all(grid[r][c2+1]==col for r in range(r1,r2+1))
     if not(canup or candown or canleft or canright): raw.append((r2-r1+1,c2-c1+1,r1+1,c1+1,r2+1,c2+1,col))
